interface Message {
  id: string;
  role: 'user' | 'assistant' | 'system';
  content: string;
  timestamp: number;
  citations?: Citation[];
  toolCalls?: ToolCall[];
}

interface Citation {
  documentId: string;
  chunkId: string;
  text: string;
  score: number;
}

interface ConversationState {
  messages: Message[];
  contextWindow: number;
  maxTokens: number;
}

class ConversationManager {
  private state: ConversationState;

  constructor(maxTokens: number = 4000) {
    this.state = {
      messages: [],
      contextWindow: 0,
      maxTokens,
    };
  }

  addMessage(message: Omit<Message, 'id' | 'timestamp'>): string {
    const id = crypto.randomUUID();
    const newMessage: Message = {
      ...message,
      id,
      timestamp: Date.now(),
    };

    this.state.messages.push(newMessage);
    this.updateContextWindow();

    // Prune if over limit
    this.pruneToContextLimit();

    return id;
  }

  private updateContextWindow() {
    // Estimate tokens (rough approximation: 4 chars per token)
    this.state.contextWindow = this.state.messages.reduce(
      (total, msg) => total + Math.ceil(msg.content.length / 4),
      0
    );
  }

  private pruneToContextLimit() {
    while (this.state.contextWindow > this.state.maxTokens && this.state.messages.length > 1) {
      // Keep system message, remove oldest user/assistant pair
      const firstUserIndex = this.state.messages.findIndex(m => m.role === 'user');
      if (firstUserIndex > 0) {
        this.state.messages.splice(firstUserIndex, 2); // Remove user + assistant
        this.updateContextWindow();
      } else {
        break;
      }
    }
  }

  getMessagesForAPI(): Message[] {
    return this.state.messages;
  }

  getCitations(): Citation[] {
    return this.state.messages
      .flatMap(m => m.citations || []);
  }
}
